/* The ring of /dev/audio and /dev/adpcm (drivers/audioring.h): the sound
 * records of the tone demo (tools/mknnv.py, generated by the Makefile) written
 * in pieces of every size while the "interrupt" takes samples now and then
 * come out as the Python decoder's samples; long records split into blocks,
 * records without codes, a state that jumps (a rewind), a full ring, bad
 * records; PCM goes through unchanged. */
#include "../../drivers/audioring.h"
#include "check.h"
#include <stdlib.h>

static uint8_t *load(const char *path, size_t *size)
{
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    *size = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *p = malloc(*size ? *size : 1);
    if (fread(p, 1, *size, f) != *size) exit(1);
    fclose(f);
    return p;
}

static uint8_t mem[4096];
static uint8_t got[1 << 20];
static size_t ngot;
static int underruns, broken;

/* The interrupt: take up to n samples. */
static void drain(struct audio_ring *r, uint32_t n)
{
    while (n--) {
        int s = ar_next(r);
        if (s < 0) { ++underruns; return; }
        if (ngot < sizeof got) got[ngot++] = (uint8_t)s;
    }
}

/* Write all of data in pieces of `piece` bytes (each piece queued over as many
 * calls as the ring needs), taking `every` samples between calls. */
static void feed(struct audio_ring *r, const uint8_t *data, size_t size, uint32_t piece, uint32_t every)
{
    for (size_t at = 0; at < size;) {
        uint32_t k = size - at < piece ? (uint32_t)(size - at) : piece;
        uint32_t done = 0;
        while (done < k) {
            done += ar_put(r, data + at + done, k - done);
            if (r->bad || ar_used(r) > r->size) { ++broken; return; }
            if (done < k) drain(r, every ? every : 64);
        }
        at += k;
        drain(r, every);
    }
}

static void finish(struct audio_ring *r)
{
    while (!ar_empty(r)) drain(r, 1);
}

/* The sound records of a file, back to back, and their samples by lib/nnv.h. */
static uint8_t *sound_of(const uint8_t *nnv, size_t size, size_t *out, uint8_t *pcm, size_t *npcm)
{
    uint8_t *s = malloc(size);
    *out = *npcm = 0;
    for (size_t at = NNV_HEADER; at + NNV_RECORD <= size;) {
        uint32_t len = nnv_u16(nnv + at + 1);
        if (nnv[at] == NNV_AUDIO) {
            memcpy(s + *out, nnv + at, NNV_RECORD + len);
            *out += NNV_RECORD + len;
            struct nnv_adpcm a;
            nnv_adpcm_start(&a, nnv + at + NNV_RECORD);
            nnv_adpcm_feed(&a, nnv + at + NNV_RECORD + 3, len - 3, pcm + *npcm);
            *npcm += 2 * (len - 3);
        }
        at += NNV_RECORD + len;
    }
    return s;
}

/* A record of n codes from state (pred, index). */
static size_t record(uint8_t *p, int16_t pred, uint8_t index, const uint8_t *codes, uint32_t n)
{
    p[0] = NNV_AUDIO;
    p[1] = (uint8_t)(n + 3);
    p[2] = (uint8_t)((n + 3) >> 8);
    p[3] = (uint8_t)pred;
    p[4] = (uint8_t)((uint16_t)pred >> 8);
    p[5] = index;
    memcpy(p + 6, codes, n);
    return 6 + n;
}

int main(void)
{
    struct audio_ring r;
    size_t size, pcm_size, nsound, npcm;
    uint8_t *nnv = load("../../build/host/nnv_tone.nnv", &size);
    uint8_t *pcm = load("../../build/host/nnv_tone.pcm", &pcm_size);
    static uint8_t mine[1 << 17];
    uint8_t *sound = sound_of(nnv, size, &nsound, mine, &npcm);
    CHECK(npcm == pcm_size && !memcmp(mine, pcm, pcm_size));
    CHECK(nsound > 10000);

    /* Every piece size from 1 to 64 and some larger, with rings of 1 and 2
     * KiB and a small one, drained fast and slowly. */
    uint32_t pieces[] = { 1, 2, 3, 5, 6, 7, 131, 132, 262, 1000, 4096, 100000 };
    uint32_t rings[] = { 64, 1024, 2048 };
    uint32_t everies[] = { 0, 3, 100 };
    int bad = 0, runs = 0;
    for (unsigned ri = 0; ri < 3; ++ri)
        for (unsigned ei = 0; ei < 3; ++ei)
            for (uint32_t pi = 0; pi < sizeof pieces / sizeof pieces[0] + 64; ++pi) {
                uint32_t piece = pi < 64 ? pi + 1 : pieces[pi - 64];
                if (pi < 64 && ri != 1) continue;
                ar_init(&r, mem, rings[ri], 1);
                ngot = 0;
                feed(&r, sound, nsound, piece, everies[ei]);
                finish(&r);
                ++runs;
                if (ngot != pcm_size || memcmp(got, pcm, pcm_size)) {
                    if (!bad++) fprintf(stderr, "ring %u, every %u, piece %u: %zu samples\n",
                                        rings[ri], everies[ei], piece, ngot);
                }
            }
    CHECK_EQ_INT(bad, 0);
    CHECK_EQ_INT(broken, 0);
    CHECK(runs > 200);

    /* A full 1 KiB ring of the demo's records holds 248 ms (3% headers). */
    ar_init(&r, mem, 1024, 1);
    uint32_t taken = ar_put(&r, sound, (uint32_t)nsound);
    CHECK(taken < nsound);
    ngot = 0;
    underruns = 0;
    drain(&r, 100000);
    CHECK(ngot >= 1980 && ngot <= 2048);
    CHECK(underruns == 1);

    /* Long records go on in blocks that keep the state; a record without
     * codes; a state that jumps back to the start (a rewind). */
    static uint8_t codes[1000], stream[4000], want[8000];
    for (unsigned i = 0; i < sizeof codes; ++i) codes[i] = (uint8_t)(i * 37u + (i >> 3));
    size_t n = record(stream, 1000, 20, codes, 1000);
    n += record(stream + n, 5, 3, codes, 0);
    n += record(stream + n, -2000, 40, codes + 7, 300);
    n += record(stream + n, 1000, 20, codes, 255);
    n += record(stream + n, 32767, 88, codes, 256);
    size_t w = 0;
    for (size_t at = 0; at < n;) {
        uint32_t len = nnv_u16(stream + at + 1);
        struct nnv_adpcm a;
        nnv_adpcm_start(&a, stream + at + 3);
        nnv_adpcm_feed(&a, stream + at + 6, len - 3, want + w);
        w += 2 * (len - 3);
        at += 3 + len;
    }
    for (uint32_t piece = 1; piece < 2000; piece = piece * 3 + 1) {
        ar_init(&r, mem, 1024, 1);
        ngot = 0;
        feed(&r, stream, n, piece, 7);
        finish(&r);
        CHECK(ngot == w && !memcmp(got, want, w));
    }
    CHECK_EQ_INT(broken, 0);

    /* Nothing plays until codes come: a record header alone queues nothing. */
    ar_init(&r, mem, 1024, 1);
    CHECK_EQ_INT(ar_put(&r, stream, 6), 6);
    CHECK_EQ_INT(ar_used(&r), 0);
    CHECK_EQ_INT(ar_next(&r), -1);
    CHECK_EQ_INT(ar_put(&r, stream + 6, 1), 1);
    CHECK_EQ_INT(ar_used(&r), 5);
    CHECK(ar_next(&r) >= 0 && ar_next(&r) >= 0 && ar_empty(&r));
    CHECK_EQ_INT(ar_next(&r), -1);                     /* the rest of the block has not come */

    /* Bad records: another type, too short, a step index above 88. */
    uint8_t other[6] = { NNV_DELTA, 3, 0, 0, 0, 0 }, shortrec[6] = { NNV_AUDIO, 2, 0, 0, 0, 0 },
            index[6] = { NNV_AUDIO, 4, 0, 0, 0, 89 };
    const uint8_t *bads[] = { other, shortrec, index };
    for (unsigned i = 0; i < 3; ++i) {
        ar_init(&r, mem, 1024, 1);
        ar_put(&r, bads[i], 6);
        CHECK(r.bad);
        CHECK_EQ_INT(ar_used(&r), 0);
        r.bad = 0;                                     /* the writer starts over */
        CHECK_EQ_INT(ar_put(&r, stream, 7), 7);
        CHECK(!r.bad && ar_used(&r) == 5);
    }

    /* PCM: the bytes themselves, a ring full at its size. */
    ar_init(&r, mem, 1024, 0);
    static uint8_t raw[3000];
    for (unsigned i = 0; i < sizeof raw; ++i) raw[i] = (uint8_t)(i * 7u);
    CHECK_EQ_INT(ar_put(&r, raw, sizeof raw), 1024);
    ngot = 0;
    drain(&r, 10);
    CHECK_EQ_INT(ar_put(&r, raw + 1024, sizeof raw), 10);
    feed(&r, raw + 1034, sizeof raw - 1034, 77, 5);
    finish(&r);
    CHECK(ngot == sizeof raw && !memcmp(got, raw, sizeof raw));
    return check_summary("test_audio");
}
